bool isSorted(List<int> lst) {
  int n = lst.length;

  // If there are no elements or only one element, it's considered sorted.
  if(n <= 1){
    return true; 
  }

  // Check each pair of adjacent items and ensure they're ordered correctly. 
  for(int i=0;i<n-1;++i){   
      if(lst[i] > lst[i+1]){
          return false;   // Early exit when unsorted found.
       }      
     }

  // All checks passed so far implies all pairs were checked & correct - hence fully sorted!
  return true;

}
